// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new X_WALLET(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg));
        amount = bound(amount, 1, 10 ether);
        unlockTime = bound(unlockTime, 0, 2**128);

        uint256 ts = block.timestamp + 1;
        vm.warp(ts);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // The most recent successful Put must be recorded as the LAST history entry
        // with exactly (this sender, this value, this timestamp).
        try lg.History(0) returns (address s, string memory, uint256 v, uint256 t) {
            assertTrue(s == actor && v == amount && t == ts);
        } catch {
            assertTrue(false);
        }
    }
}
